import unittest
from candidate import is_palindrome

class TestPalindrome(unittest.TestCase):
    def test_empty_string(self):
        self.assertTrue(is_palindrome(''))

    def test_single_char(self):
        self.assertTrue(is_palindrome('a'))

    def test_even_length_palindrome(self):
        self.assertTrue(is_palindrome('abba'))

    def test_odd_length_palindrome(self):
        self.assertTrue(is_palindrome('abcba'))

    def test_case_sensitivity(self):
        self.assertFalse(is_palindrome('RaceCar'))

    def test_non_palindrome(self):
        self.assertFalse(is_palindrome('hello'))

    def test_palindrome_with_spaces(self):
        self.assertFalse(is_palindrome('a man a plan a canal panama'))

    def test_palindrome_with_punctuation(self):
        self.assertFalse(is_palindrome('A man, a plan, a canal: Panama'))

    def test_unicode_palindrome(self):
        self.assertTrue(is_palindrome('éé'))

    def test_all_same_char(self):
        self.assertTrue(is_palindrome('aaaa'))

    def test_mixed_case_palindrome(self):
        self.assertTrue(is_palindrome('AbBa'))

    def test_long_palindrome(self):
        self.assertTrue(is_palindrome('abcdcba'))

    def test_non_ascii_palindrome(self):
        self.assertTrue(is_palindrome('こんにちは'))

    def test_none_input(self):
        with self.assertRaises(TypeError):
            is_palindrome(None)

    def test_non_string_input(self):
        with self.assertRaises(TypeError):
            is_palindrome(123)

    def test_string_with_numbers(self):
        self.assertFalse(is_palindrome('a1b2b1a'))

    def test_string_with_numbers_palindrome(self):
        self.assertTrue(is_palindrome('a1a'))

    def test_palindrome_with_whitespace(self):
        self.assertFalse(is_palindrome('a b a'))

    def test_palindrome_with_whitespace_stripped(self):
        self.assertTrue(is_palindrome('a b a'.strip()))
